import { NextResponse, type NextRequest } from 'next/server'
import { z } from 'zod'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { RPC, type TaxOssQuarterlyExportResult } from '@/lib/payments/contracts'
import { adminExportRatelimit } from '@/lib/rate-limit'
import { requirePlatformAdmin } from '@/lib/admin/require-platform-admin'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'

const BodySchema = z.object({
  studioId: z.string().uuid(),
  year: z.number().int().min(2024).max(2099),
  quarter: z.union([z.literal(1), z.literal(2), z.literal(3), z.literal(4)]),
})

export async function POST(req: NextRequest): Promise<Response> {
  const auth = await requirePlatformAdmin(req)
  if (auth instanceof NextResponse) return auth

  const ip = getClientIp(req)
  const rl = await adminExportRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'rate_limited' }, { status: 429 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'invalid_json' }, { status: 400 })
  }

  const parsed = BodySchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: 'validation', issues: parsed.error.issues }, { status: 400 })
  }

  const supabase = createServiceRoleClient()

  // §S13.3 — tax_oss_quarterly_export not yet in generated types.ts; cast to untyped rpc.
  const rpc = supabase.rpc.bind(supabase) as unknown as (
    fn: string,
    args: Record<string, unknown>,
  ) => Promise<{ data: unknown; error: { message: string } | null }>

  const { data, error } = await rpc(RPC.TAX_OSS_QUARTERLY_EXPORT, {
    p_studio_id: parsed.data.studioId,
    p_year: parsed.data.year,
    p_quarter: parsed.data.quarter,
  })

  if (error) {
    logger.error({ studio_id: parsed.data.studioId, err: error }, 'tax_oss_quarterly_export RPC failed')
    return NextResponse.json({ error: 'export_failed' }, { status: 500 })
  }

  const result = data as TaxOssQuarterlyExportResult

  // Build CSV
  const lines: string[] = []
  lines.push('jurisdiction,amount_collected_cents,amount_remitted_cents,amount_outstanding_cents,registration_status')
  for (const j of result.jurisdictions) {
    lines.push(
      [
        j.jurisdiction,
        j.amount_collected_cents,
        j.amount_remitted_cents,
        j.amount_outstanding_cents,
        j.registration_status ?? '',
      ].join(','),
    )
  }
  lines.push(`TOTAL_EU_COLLECTED,${result.total_eu_collected_cents},,,`)
  lines.push(`TOTAL_EU_OUTSTANDING,${result.total_eu_outstanding_cents},,,`)
  const csv = lines.join('\n') + '\n'

  await logAuditAction(
    auth.userId,
    'admin_tax_oss_export',
    { type: 'studio', id: parsed.data.studioId },
    { year: parsed.data.year, quarter: parsed.data.quarter, period: result.period },
    parsed.data.studioId,
  )

  return new Response(csv, {
    status: 200,
    headers: {
      'Content-Type': 'text/csv; charset=utf-8',
      'Content-Disposition': `attachment; filename="oss-${parsed.data.studioId}-${result.period}.csv"`,
    },
  })
}
