/**
 * PATCH /api/settings/payments/tip-pool
 *
 * Owner/admin-only endpoint: toggle the studio's tip routing mode.
 *
 * Auth:  owner | admin (receptionists and artists cannot change this setting).
 * Rate:  authedRatelimit (60 req/min per IP).
 *
 * Body:  { enabled: boolean }
 *
 * Flow:
 *   1. Auth + studio role check (owner/admin only).
 *   2. Rate limit.
 *   3. Zod body validation.
 *   4. Read current value for audit delta.
 *   5. Update studios.tip_pool_enabled via service-role client (RLS restricts direct write).
 *   6. Audit log: tip_pool_mode_changed.
 *   7. Return 200 { tip_pool_enabled: boolean }.
 *
 * Success:    200 { tip_pool_enabled: boolean }
 * Forbidden:  403 { error }
 * Validation: 400 { error, issues }
 * Server err: 500 { error }
 */

import type { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const ALLOWED_ROLES = ['owner', 'admin'] as const
type AllowedRole = typeof ALLOWED_ROLES[number]

// ---------------------------------------------------------------------------
// Input schema
// ---------------------------------------------------------------------------

const TipPoolBodySchema = z.object({
  enabled: z.boolean(),
})

type TipPoolBody = z.infer<typeof TipPoolBodySchema>

// ---------------------------------------------------------------------------
// Route handler
// ---------------------------------------------------------------------------

export async function PATCH(req: NextRequest) {
  // 1. Rate limit
  const ip = getClientIp(req)
  const { success: rateLimitOk } = await authedRatelimit.limit(ip)
  if (!rateLimitOk) {
    return Response.json({ error: 'Rate limited' }, { status: 429 })
  }

  // 2. Auth — session-scoped client
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // 3. Resolve studio membership + role (owner/admin only)
  const { data: member, error: memberErr } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  if (memberErr || !member) {
    return Response.json({ error: 'No active studio membership' }, { status: 403 })
  }

  const role = member.role as string
  if (!(ALLOWED_ROLES as readonly string[]).includes(role)) {
    return Response.json(
      { error: 'Only studio owners and admins can change tip routing.' },
      { status: 403 },
    )
  }

  const studioId: string = member.studio_id

  // 4. Parse + validate body
  let body: TipPoolBody
  try {
    const raw = await req.json()
    body = TipPoolBodySchema.parse(raw)
  } catch (err) {
    if (err instanceof z.ZodError) {
      return Response.json({ error: 'Validation failed', issues: err.issues }, { status: 400 })
    }
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  // 5. Read current value for audit delta
  // §S13.3 — tip_pool_enabled column added by Track C migration; cast through unknown.
  const { data: currentRow, error: readErr } = await supabase
    .from('studios')
    .select('tip_pool_enabled')
    .eq('id', studioId)
    .single()

  if (readErr) {
    logger.error({ studio_id: studioId, err: readErr }, 'tip-pool: failed to read current value')
    return Response.json({ error: 'Failed to read current tip routing setting.' }, { status: 500 })
  }

  const currentEnabled =
    (currentRow as unknown as { tip_pool_enabled: boolean | null }).tip_pool_enabled === true

  // 6. Update via service-role client (bypass RLS for this settings write)
  const serviceSupabase = createServiceRoleClient()
  // §S13.3 — tip_pool_enabled added by Track C migration; cast through unknown to bypass
  // generated types until pnpm db:types is rerun after Track C migration lands.
  const { error: updateErr } = await serviceSupabase
    .from('studios')
    .update({ tip_pool_enabled: body.enabled } as unknown as Parameters<
      ReturnType<typeof serviceSupabase.from>['update']
    >[0])
    .eq('id', studioId)

  if (updateErr) {
    logger.error(
      { studio_id: studioId, enabled: body.enabled, err: updateErr },
      'tip-pool: failed to update studios.tip_pool_enabled',
    )
    return Response.json({ error: 'Failed to update tip routing setting.' }, { status: 500 })
  }

  // 7. Audit log (non-fatal)
  await logAuditAction(
    user.id,
    'tip_pool_mode_changed',
    { type: 'studio', id: studioId },
    {
      from: currentEnabled,
      to: body.enabled,
      by: user.id,
      role: role as AllowedRole,
    },
    studioId,
  )

  logger.info(
    { studio_id: studioId, from: currentEnabled, to: body.enabled, user_id: user.id },
    'tip pool mode changed',
  )

  return Response.json({ tip_pool_enabled: body.enabled })
}
```

